cd /home/ctfplayer/ctf_files && cat > extract_strings.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    FILE *fp = fopen("brrr", "rb");
    if (fp == NULL) {
        perror("Error opening file");
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    char *buffer = malloc(size);
    if (buffer == NULL) {
        perror("Error allocating memory");
        fclose(fp);
        return 1;
    }

    fread(buffer, 1, size, fp);
    fclose(fp);

    // Print strings of at least 5 characters
    for (long i = 0; i < size - 4; i++) {
        int is_string = 1;
        for (int j = 0; j < 5; j++) {
            if (buffer[i+j] < 32 || buffer[i+j] > 126) {
                is_string = 0;
                break;
            }
        }

        if (is_string) {
            int len = 0;
            while (i+len < size && buffer[i+len] >= 32 && buffer[i+len] <= 126) {
                len++;
            }

            printf("%08lx: ", i);
            for (int j = 0; j < len; j++) {
                printf("%c", buffer[i+j]);
            }
            printf("\n");

            i += len - 1;
        }
    }

    free(buffer);
    return 0;
}
EOF

gcc extract_strings.c -o extract_strings && ./extract_strings | grep -i brrr

