#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    const char *magic_headers[] = {
        "BRRR",         // Custom magic
        "BRR\x00",      // Custom magic with null byte
        "BRRT",         // Custom magic
        "brrt",         // Lowercase
        "FUZZ",         // Fuzzing related
        "CRASH",        // Crash report related
        "\x7FBRR",      // ELF-style with BRR
        "BRR\x0AITO",   // With newline
        "BRR\x0DITO",   // With CR
        "BRRITO",       // Direct from strings
        "brrrito",      // Lowercase
        "FUZZY"         // Another fuzzing term
    };

    int num_headers = sizeof(magic_headers) / sizeof(magic_headers[0]);

    for (int i = 0; i < num_headers; i++) {
        char filename[64];
        sprintf(filename, "test_magic_%d.bin", i);

        FILE *f = fopen(filename, "wb");
        if (!f) {
            perror("Failed to create test file");
            continue;
        }

        size_t magic_len = strlen(magic_headers[i]);
        fwrite(magic_headers[i], 1, magic_len, f);

        // Add some dummy content
        char dummy[100];
        memset(dummy, 'A', sizeof(dummy));
        fwrite(dummy, 1, sizeof(dummy), f);

        fclose(f);

        // Try to run with this file
        char command[128];
        sprintf(command, "./brrr %s > /dev/null 2>&1; echo \"Exit code for %s: $?\"", 
                filename, filename);
        system(command);
    }

    return 0;
}
EOF

gcc fuzz_headings.c -o fuzz_headings && ./fuzz_headings
